  ['title' => 'Labor and Establishment Services', 'body' => '<ul><li>3. Labor and Establishment Services</li><li>Expatriate labor approval after a field visit to assess workforce requirements.</li><li>Competitive advantage: work permit at SAR 100 only for factories linked to Qiwa platform.</li><li>Electronic factory card.</li><li>Factory data updates and factory status inquiry.</li></ul>', 'icon' => ''],
